def cards():
 out=''
 for i,w in enumerate(WORKS,1):
  out+=f'''<article class="work" data-category="{w['cat']}"><button class="work-open" data-work="{w['id']}" aria-label="{w['name']}の詳細を見る"><figure>{img(w['file'],w['name'])}<span class="work-view" aria-hidden="true">作品を見る ↗</span></figure><div class="work-meta"><span>{i:02d} / {w['material']}</span><span aria-hidden="true">↗</span></div><h3>{w['name']}</h3><p>{w['use']}</p></button></article>'''
