def about(c):
 return f'''<section class="page-intro wrap">{label('ABOUT ONLYYUUKA')}<h1>布と向き合う、<br>ひとりの作り手。</h1><p>リメイクアーティスト、onlyyuukaについて。</p></section><section class="about-feature wrap"><figure>{img('hands-process.webp','布を縫う手元のイメージ',eager=True)}<figcaption>イメージ写真 / ご本人の制作風景に差し替える想定です。</figcaption></figure><div>{label('REMAKE ARTIST')}<h2>onlyyuuka</h2><p>帯や古着など、使われなくなった素材から、バッグや布小物、テーブルに添える作品を制作しています。</p><p>同じ布でも、どの柄を切り取るかで表情が変わる。その違いを活かしながら、もう一度手に取って使えるかたちを考えます。</p><p class="sample-note">紹介文は提案原稿です。活動のきっかけ・経歴は、ご本人へのヒアリング後に加えます。</p></div></section><section class="values wrap"><div>{label('AN APPROACH TO MAKING')}<h2>一枚の布から、<br>考えること。</h2></div><div><article><span>01</span><h3>どの表情を、残そう。</h3><p>織り柄や色の重なり。もとの素材の特徴を、次の作品の手がかりに。</p></article><article><span>02</span><h3>どんな場面で、使おう。</h3><p>食卓に置く、持ち歩く、部屋に飾る。使う場面に合うかたちを考えます。</p></article><article><span>03</span><h3>組み合わせで、何が変わる。</h3><p>外と内、柄と無地。布同士の組み合わせも、一点ごとの違いになります。</p></article></div></section>{contactband()}{newsletter()}'''
def works(c):
 return f'''<section class="page-intro wrap">{label('WORKS / THE COLLECTION')}<h1>もとの布を、<br>知るとおもしろい。</h1><p>帯から、テーブルランナーへ。古布から、毎日の小物へ。<br>素材と使う場面から、作品をご覧ください。</p></section><section class="all-works wrap"><div class="filters" role="group" aria-label="作品のカテゴリ"><button class="active" data-filter="all" aria-pressed="true">すべて <span>03</span></button><button data-filter="interior" aria-pressed="false">インテリア・布小物 <span>02</span></button><button data-filter="bag" aria-pressed="false">バッグ・ポーチ <span>01</span></button></div><p id="filter-result" class="sr-only" aria-live="polite">3作品を表示</p><div class="works-grid">{cards()}</div><p class="sample-note">掲載作品は既存資料からの制作例です。現在の仕様・受付状況を示すものではありません。</p></section><section class="faq wrap"><div>{label('ABOUT THE WORKS')}<h2>作品について。</h2></div><div><details><summary>同じ柄の作品はありますか？<span aria-hidden="true">＋</span></summary><p>素材や柄の取り方によって作品の表情が変わります。再制作の可否は、作品ごとにご確認いただく想定です。</p></details><details><summary>自分の布を使った制作は相談できますか？<span aria-hidden="true">＋</span></summary><p>オーダーの受付範囲は、正式公開前に確認します。お問い合わせの見本では、素材や希望するかたちをお伝えいただけます。</p></details><details><summary>お手入れ方法は？<span aria-hidden="true">＋</span></summary><p>使用する布と仕立てによって異なります。作品ごとに確認したお手入れ方法を、正式掲載時にご案内します。</p></details></div></section>{contactband()}{newsletter()}'''
def contact(c):
 return f'''<section class="page-intro wrap">{label('CONTACT')}<h1>まだ、決まって<br>いなくても。</h1><p>作品のこと、展示のこと、一緒につくってみたいこと。<br>まずは、ご相談の内容をお聞かせください。</p></section><section class="contact-layout wrap"><aside><h2>ご相談いただけること</h2><ul><li>作品についてのご質問</li><li>オーダー制作のご相談</li><li>展示・イベントのお誘い</li><li>取材・掲載について</li><li>コラボレーションのご相談</li></ul><p>ご希望や予定が具体的でなくても大丈夫。<br>今お考えのことから、お聞かせください。</p><p class="sample-note">ご提案用のフォームです。入力内容は送信・保存されません。個人情報は入れずにお試しください。</p></aside><div><form id="contact-form"><label for="name">お名前 <span>必須</span></label><input id="name" name="name" required maxlength="80" autocomplete="off" placeholder="例：山田 花子"><label for="email">メールアドレス <span>必須</span></label><input id="email" name="email" type="email" required maxlength="254" autocomplete="off" placeholder="例：hello@example.com"><label for="type">お問い合わせ種別 <span>必須</span></label><select id="type" name="type" required><option value="">選択してください</option><option>作品について</option><option>オーダー相談</option><option>取材・掲載</option><option>展示・イベント</option><option>コラボ依頼</option><option>その他</option></select><label for="message">お問い合わせ内容 <span>必須</span></label><textarea id="message" name="message" rows="6" required maxlength="3000" placeholder="気になる作品や、ご相談の内容をお聞かせください。"></textarea><label class="consent"><input type="checkbox" required><span>送信されないサンプルであることを確認しました</span></label><button class="button" type="submit">入力内容を確認する <span aria-hidden="true">↗</span></button></form><section id="contact-result" class="confirmation" hidden tabindex="-1" aria-labelledby="confirmation-title"><p class="eyebrow">PREVIEW</p><h2 id="confirmation-title">入力内容を確認しました。</h2><p>このサンプルでは送信していません。<br>正式公開時に、お問い合わせの送受信を接続します。</p><dl id="confirmation-values"></dl><button id="edit-contact" class="button" type="button">入力内容を修正する <span aria-hidden="true">←</span></button></section></div></section>{newsletter()}'''
# Each concept is explicitly built only after its predecessor has been verified.
for c in sys.argv[1:] or ['gallery']:
 if c not in CONCEPTS: raise SystemExit(c)
 target=ROOT/c; target.mkdir(parents=True,exist_ok=True)
